server.tool(
  "quick_start_report",
  "Runs a built-in Quick Start portfolio through the full financial simulation and returns a Markdown report: plan issues, net worth trajectory, annual cash flow, lifetime tax breakdown, and per-asset summary. The ages genuinely reshape the plan \u2014 every asset date and life-event trigger is derived from them.",
  {
    profile: external_exports3.enum(PROFILE_KEYS).default("midCareer").describe(`Which Quick Start profile to simulate. One of: ${PROFILE_KEYS.join(", ")}. Filing status comes from the profile itself.`),
    startAge: external_exports3.number().int().min(20).max(90).optional().describe("Override the profile's start age. Shifts every asset date and phase boundary."),
    retirementAge: external_exports3.number().int().min(30).max(95).optional().describe("Override the profile's retirement age. Moves the Accumulate/Retire transition."),
    finishAge: external_exports3.number().int().min(40).max(110).optional().describe("Override the profile's finish age. Sets where the simulation ends."),
    inflationRate: external_exports3.number().min(0).max(0.15).optional().describe("Annual inflation as a decimal (e.g. 0.031 for 3.1%). Defaults to 3.1%."),
    includeReconciliation: external_exports3.boolean().default(false).describe("Include engine-diagnostic findings (bookkeeping that does not reconcile). These are notes about the engine, not about the finances."),
    monteCarlo: external_exports3.number().int().min(100).max(5e3).optional().describe("Number of Monte Carlo simulations to run. Omit for none. Adds a percentile table to the report. Sampling is random and unseeded, so these figures change between calls while the rest of the report does not.")
  },
  guard(async ({ profile, startAge, retirementAge, finishAge, inflationRate, includeReconciliation, monteCarlo }) => {
    const spec = planFromProfile(profile, { startAge, retirementAge, finishAge });
    if (inflationRate != null) spec.settings.inflationRate = inflationRate;
    const { handle, portfolio, issues } = await runPlanCached(spec, { includeReconciliation });
    const mc = monteCarlo ? await runMonteCarloFor(spec, { numSimulations: monteCarlo }) : null;
    return { content: [{ type: "text", text: reportFor(handle, portfolio, issues, mc) }] };
  })
);
server.tool(
  "run_plan",
  "Runs a caller-supplied portfolio through the full simulation and returns the same Markdown report as quick_start_report. The plan format is exactly what the Charting Finance app's Share link encodes, so a portfolio exported from the app can be passed straight in.",
  {
    plan: external_exports3.object({
      name: external_exports3.string().optional(),
      settings: external_exports3.object({
        inflationRate: external_exports3.number().min(0).max(0.15).optional(),
        filingAs: external_exports3.enum(["Single", "MFJ"]).optional().describe("Selects the tax tables, contribution limits and home-sale exclusion."),
        startAge: external_exports3.number().int().optional(),
        retirementAge: external_exports3.number().int().optional(),
        finishAge: external_exports3.number().int().optional()
      }).optional(),
      // z.record needs BOTH a key and a value type on zod 4 — the one-argument
      // form throws while building the JSON schema, which surfaces as a
      // tools/list failure rather than an error here.
      modelAssets: external_exports3.array(external_exports3.record(external_exports3.string(), external_exports3.any())).describe("Assets in the app's serialized form (ModelAsset.toJSON())."),
      lifeEvents: external_exports3.array(external_exports3.record(external_exports3.string(), external_exports3.any())).optional().describe("Life events (ModelLifeEvent.toJSON()). Omitting these means no phase ever transitions: salary never closes and retirement transfers never activate.")
    }).describe("A plan in the app's share format."),
    includeReconciliation: external_exports3.boolean().default(false),
    monteCarlo: external_exports3.number().int().min(100).max(5e3).optional().describe("Number of Monte Carlo simulations to run. Omit for none. Sampling is random and unseeded, so these figures change between calls.")
  },
  guard(async ({ plan, includeReconciliation, monteCarlo }) => {
    const { handle, portfolio, issues } = await runPlanCached(plan, { includeReconciliation });
    const mc = monteCarlo ? await runMonteCarloFor(plan, { numSimulations: monteCarlo }) : null;
    return { content: [{ type: "text", text: reportFor(handle, portfolio, issues, mc) }] };
  })
);
server.tool(
  "explain_issue",
  "Answers WHY a finding from a plan's report happened, as a causal chain: the sequence of engine operations that produced it, plus everything else that happened in the same step. Requires a run handle from quick_start_report or run_plan.",
  {
    handle: external_exports3.string().describe("Run handle from a report, e.g. plan_3f9c1a2b04. Stable: the same plan always yields the same handle, and an older one still works \u2014 the server re-runs it if needed."),
    issueId: external_exports3.string().describe("Finding id, e.g. 'plan-exhaustion', 'unfunded-obligation', 'funding-ran-dry', 'contribution-capped'. The report lists the ids present in that run."),
    assetName: external_exports3.string().optional().describe("Disambiguates when several assets carry the same finding."),
    limit: external_exports3.number().int().min(1).max(20).default(3).describe("How many occurrences to explain, earliest first.")
  },
  guard(async ({ handle, issueId, assetName, limit }) => {
    const result = explainIssue(await getRun(handle), issueId, { assetName, limit });
    return { content: [{ type: "text", text: explainIssueMarkdown(result) }] };
  })
);
server.tool(
  "explain_month",
  "Shows what the engine did at a point in a plan, with the causal chain behind each event. Use this to investigate a month that looks surprising in the projection table. Requires a run handle from quick_start_report or run_plan.",
  {
    handle: external_exports3.string().describe("Run handle from a report, e.g. plan_3f9c1a2b04."),
    date: external_exports3.string().optional().describe("Month to inspect as 'YYYY-MM', e.g. '2051-11'. Omit to search the whole plan (pair with assetName or eventType so the result stays useful)."),
    assetName: external_exports3.string().optional().describe("Restrict to one asset, by its display name."),
    eventType: external_exports3.enum(Object.values(EventType)).optional().describe("Restrict to one kind of engine event."),
    limit: external_exports3.number().int().min(1).max(50).default(10)
  },
  guard(async ({ handle, date: date5, assetName, eventType, limit }) => {
    const result = explainAt(await getRun(handle), { date: date5, assetName, eventType, limit });
    return { content: [{ type: "text", text: explainAtMarkdown(result) }] };
  })
);
server.tool(
  "share_link",
  "Turns a run into a link that opens the same plan in the Charting Finance web app for full interactive visualization \u2014 charts, timeline, projections. The plan is encoded in the URL fragment, which browsers never send to the server, so opening the link does not upload the portfolio anywhere; the page reads it locally and asks before importing. Give the link to the user and let them open it. Requires a run handle from quick_start_report or run_plan.",
  {
    handle: external_exports3.string().describe("Run handle from a report, e.g. plan_3f9c1a2b04."),
    name: external_exports3.string().optional().describe("Name the shared portfolio arrives under. Defaults to the plan's own name."),
    origin: external_exports3.string().optional().describe("Where the link points. Defaults to https://charting.finance/ \u2014 override only to target a local dev server.")
  },
  guard(async ({ handle, name, origin }) => {
    const link = shareUrlFromPlan(specForHandle(handle), { name, origin });
    const lines = [
      `**Open this plan in Charting Finance:**`,
      "",
      link.url,
      "",
      `${link.assetCount} asset(s), as "${link.name}". Opening it uploads nothing \u2014 the plan travels in the URL fragment, which the browser keeps to itself. On arrival the site prompts with **Open** (view it, saved scenarios untouched) and **Open & Save** (keep it); nothing already there changes until one is chosen.`
    ];
    if (link.oversize) {
      lines.push("", `\u26A0\uFE0F This link is ${link.length.toLocaleString()} characters, past the ${SHARE_URL_SOFT_LIMIT.toLocaleString()} where mail clients and address bars start truncating. It will work if it arrives intact; sending it as a file is safer.`);
    }
    return { content: [{ type: "text", text: lines.join("\n") }] };
  })
);
server.tool(
  "plan_defaults",
  "The assumptions a new plan starts from \u2014 age, retirement age, horizon, inflation and filing status \u2014 with a plain-language gloss for each. Call this ONCE at the start of a planning conversation and state them back to the user before building anything, because a plan built on unstated defaults is a plan about someone else. Not needed for quick_start_report.",
  {},
  guard(async () => ({
    content: [{ type: "text", text: JSON.stringify(planDefaults(), null, 2) }]
  }))
);
var buildPlanShape = {
  horizonYears: external_exports3.number().int().min(1).max(80).optional().describe("How many years to project, e.g. 10. Derives finishAge from startAge. Mutually exclusive with settingsOverrides.finishAge."),
  name: external_exports3.string().optional(),
  income: external_exports3.array(external_exports3.object({
    label: external_exports3.string().describe("What to call it, e.g. 'Salary'."),
    annual: external_exports3.number().optional().describe("Gross annual amount. Give this OR monthly."),
    monthly: external_exports3.number().optional(),
    kind: external_exports3.enum(["working", "pension", "socialSecurity"]).optional().default("working"),
    growthRate: external_exports3.number().optional().describe("Annual raise rate as a decimal, e.g. 0.025.")
  })).min(1).describe("Income sources. At least one is required."),
  accounts: external_exports3.array(external_exports3.object({
    label: external_exports3.string().describe("What to call it. The wording is read for the account type: 'brokerage', 'savings', '401k', 'IRA', 'Roth' all resolve."),
    kind: external_exports3.string().optional().describe("Explicit instrument key, when the label does not say."),
    startingBalance: external_exports3.number().optional(),
    growthRate: external_exports3.number().optional()
  })).optional(),
  savingsSplit: external_exports3.array(external_exports3.object({
    from: external_exports3.string().describe("An income label."),
    to: external_exports3.string().describe("An account label."),
    percent: external_exports3.number().describe("Share OF THAT INCOME, not of the other splits. 5 to one account and 5 to another is 10% saved, not 10% each.")
  })).optional(),
  expenses: external_exports3.array(external_exports3.object({
    label: external_exports3.string(),
    monthly: external_exports3.number().optional(),
    annual: external_exports3.number().optional()
  })).optional(),
  settingsOverrides: external_exports3.object({
    startAge: external_exports3.number().int().optional(),
    retirementAge: external_exports3.number().int().optional(),
    finishAge: external_exports3.number().int().optional(),
    inflationRate: external_exports3.number().optional(),
    filingAs: external_exports3.enum(["Single", "MFJ"]).optional()
  }).optional().describe("Anything the user stated. Whatever is omitted comes from plan_defaults and is reported as a default in the ledger.")
};
server.tool(
  "build_plan",
  "Turns a described situation into a plan spec that run_plan can simulate \u2014 you supply meaning (income, accounts, what share is saved) and this supplies instruments, dates, rates and phases. It RUNS NOTHING: pass the returned spec to run_plan for numbers. It refuses or asks a question when the description does not determine a plan, and that refusal is the point \u2014 relay the question rather than guessing past it. Every value it supplied is listed in the ledger with where it came from; state the structural additions and the assumptions to the user when you show the plan.",
  buildPlanShape,
  guard(async (intent) => {
    try {
      const { spec, ledger, notes, horizon } = buildPlan(intent);
      return { content: [{ type: "text", text: JSON.stringify(
        {
          spec,
          ledger,
          notes,
          horizon,
          nextStep: "Pass `spec` to run_plan to simulate it."
        },
        null,
        2
      ) }] };
    } catch (err) {
      if (!(err instanceof PlanRefusal)) throw err;
      return { content: [{ type: "text", text: JSON.stringify({
        refused: err.reason,
        question: err.question,
        options: err.options,
        field: err.field,
        guidance: "Ask the user this question. Do not pick a value on their behalf."
      }, null, 2) }] };
    }
  })
);
var transport = new StdioServerTransport();
server.connect(transport);
